def transform(grid):
    H, W = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    def is_target(v):
        return v != bg

    for dr, dc in ((1, 1), (1, -1)):
        seen = [[False] * W for _ in range(H)]
        for r in range(H):
            for c in range(W):
                if seen[r][c]:
                    continue
                v = grid[r][c]
                if not is_target(v):
                    continue
                # collect maximal segment in this diagonal direction
                seg = []
                rr, cc = r, c
                while 0 <= rr < H and 0 <= cc < W and grid[rr][cc] == v and not seen[rr][cc]:
                    seg.append((rr, cc))
                    seen[rr][cc] = True
                    rr += dr
                    cc += dc
                if len(seg) < 2:
                    continue
                # extend from both ends
                for start, step in ((seg[0], (-dr, -dc)), (seg[-1], (dr, dc))):
                    rr, cc = start[0] + step[0], start[1] + step[1]
                    while 0 <= rr < H and 0 <= cc < W and grid[rr][cc] == bg:
                        out[rr][cc] = v
                        rr += step[0]
                        cc += step[1]
    return out
